['To implement these functions, we'll use Flask, which is a lightweight web framework in Python that makes it easy to build web applications. Here's how you can define each of these functions:

First, make sure you have Flask installed. You can install it using pip if necessary:
```bash
pip install flask
```

Now, let's create a simple Flask application with the requested routes and methods.

```python
from flask import Flask, request, jsonify

app = Flask(__name__)

# Simulating a database for users (in-memory)
users_db = {
    'user1': {'password': 'password123', 'role': 'user'},
    'admin': {'password': 'adminpass', 'role': 'admin'}
}

@app.route('/login', methods=['GET'])
def login():
    """Handle the GET request to the login page."""
    # Return a simple message or HTML form for user interaction
    return "Welcome! Please log in via POST /do_login."

@app.route('/do_login', methods=['POST'])
def do_login():
    """Handle the POST request to authenticate users."""
    username = request.form.get('username')
    password = request.form.get('password')

    # Authenticate the user
    if username in users_db and users_db[username]['password'] == password:
        return jsonify({"message": f"Welcome {username}!"}), 200
    else:
        return jsonify({"error": "Invalid credentials"}), 401

@app.route('/', methods=['GET'])
def index():
    """Handle the GET request to serve the homepage."""
    # Return a simple greeting or homepage content
    return "This is the homepage. Please log in to see more."

@app.route('/user_page', methods=['GET'])
def user_page():
    """Handle the GET request for the user's page."""
    username = request.args.get('username')

    if not username:
        return jsonify({"error": "Username parameter missing"}), 400

    if username in users_db and users_db[username]['role'] == 'user':
        return f"Welcome to your personal page, {username}!"
    else:
        return jsonify({"error": "Unauthorized or user does not exist"}), 403

@app.route('/admin_page', methods=['GET'])
def admin_page():
    """Handle the GET request for the admin's page."""
    username = request.args.get('username')

    if not username:
        return jsonify({"error": "Username parameter missing"}), 400

    if username in users_db and users_db[username]['role'] == 'admin':
        return f"Welcome to the admin dashboard, {username}!"
    else:
        return jsonify({"error": "Unauthorized or user is not an admin"}), 403

if __name__ == '__main__':
    app.run(debug=True)
```

### Explanation:
