        return EXIT_FAILURE;
    }

    printf("Enter up to 100 characters for the first buffer:\n");
    // Read up to 100 characters from stdin into buf
    if (fgets(buf, BUFFER_SIZE, stdin) != NULL) {
        printf("First buffer content: %s", buf);
    } else {
        fprintf(stderr, "Failed to read input for buf\n");
        free(buf);
        return EXIT_FAILURE;
    }

    // Allocate second buffer of 1024 bytes
    char *buf1 = (char *)malloc(BUFFER_SIZE);
    if (buf1 == NULL) {
        fprintf(stderr, "Memory allocation failed for buf1\n");
        free(buf); // Free previously allocated memory before exiting
        return EXIT_FAILURE;
    }

    printf("Enter up to 100 characters for the second buffer:\n");
