#include <stdio.h>

int scan(char *buffer, const char *format) {
    int chars_read = 0;

    // Use scanf to read input according to the format string.
    // The format "%1023[^\n]%1[\n]" ensures that at most 1023 characters are read
    // until a newline is encountered, and then it checks for the newline character itself.
    chars_read = sscanf(stdin, format, buffer);

    return chars_read;
}

int main() {
    char buffer[1024];

    printf("Enter a string: ");
    int result = scan(buffer, "%1023[^\n]%1[\n]");

    // Print the number of characters read
    printf("Number of characters read (excluding newline): %d\n", result - 1);

    // Print the actual input stored in buffer
    printf("Input: '%s'\n", buffer);

    return 0;
}
```

