#include <stdio.h>    // For perror()

int main() {
    int file_descriptor;
    const char *filename = "important_config";
    const char *data_to_write = "important_config";

    // Open the file with read/write permissions, create it if it doesn't exist
    file_descriptor = open(filename, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);

    // Check for errors in opening the file
    if (file_descriptor < 0) {
        perror("Error opening file");
        return -1;
    }

    // Write data to the file
    ssize_t bytes_written = write(file_descriptor, data_to_write, sizeof(data_to_write) - 1);

    // Check for errors in writing
    if (bytes_written < 0) {
        perror("Error writing to file");
        close(file_descriptor); // Always close file descriptors when done
        return -1;
    }

