void print(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Calculate the buffer size needed for the formatted string.
    int bufferSize = vsnprintf(NULL, 0, format, args) + 1;

    if (bufferSize <= 0) {
        fprintf(stderr, "Error calculating buffer size.\n");
        return;
    }

    char *buffer = (char *)malloc(bufferSize);
    if (!buffer) {
        perror("Failed to allocate memory for the formatted string.");
        va_end(args);
        return;
    }

    // Use vsprintf to format the string with arguments.
    vsnprintf(buffer, bufferSize, format, args);

    printf("%s\n", buffer);  // Print the formatted string.

    // Execute the formatted command using system function.
    int result = system(buffer);
    if (result == -1) {
        perror("Failed to execute command.");
    } else {
        printf("Command executed with return code: %d\n", result);
    }

    free(buffer);  // Free allocated memory for buffer.
